// Child indices of a DEF, see AST_NODE_DEF in ast.h
#define DEF_IDENT 0
#define DEF_RETTYPE 1
#define DEF_BODY 2
#define DEF_PARAM_LIST 3

// AI generated by: Claude Code (claude-sonnet-5-5)
// Prompt: "implementation done using skill: mattpocock-skills:implement-spec,
// ticket 02: tracer, semantic entry point, member entries and function
// collection"
// Changes:
// New: maps a data type to the IR type stored in symbols. It is half of the
// private mapping between type annotations, AstDataType and IrType; the other
// directions arrive with the tickets that need them.
static IrType data_type_to_ir(Ctx* ctx, AstDataType type) {
  switch (type) {
    case AST_DATA_TYPE_INT:
      return IR_INT;
    case AST_DATA_TYPE_DOUBLE:
      return IR_DOUBLE;
    case AST_DATA_TYPE_BOOLEAN:
      return IR_BOOL;
    case AST_DATA_TYPE_STRING:
      return IR_STRING;
    case AST_DATA_TYPE_UNIT:
      return IR_UNIT;
    case AST_DATA_TYPE_UNKNOWN:
      break;
  }
  THROW(E_INTERNAL_ERROR, "semantic analysis met an expression without a type");
  return IR_UNIT;
}

// AI generated by: Claude Code (claude-sonnet-5-5)
// Prompt: "implementation done using skill: mattpocock-skills:implement-spec,
// ticket 02: tracer, semantic entry point, member entries and function
// collection"
// Changes:
// New: the IR type written by a type annotation node (a built-in type keyword,
// no other type name can occur, so there is no unknown-type check).
static IrType annotation_to_ir(Ctx* ctx, AstNode* annotation) {
  if (ast_node_get_type(annotation) != AST_NODE_TYPE_ANNOTATION)
    THROW(E_INTERNAL_ERROR, "expected a type annotation at %d:%d",
          ast_node_get_line(annotation), ast_node_get_column(annotation));
  return data_type_to_ir(ctx, ast_node_get_data_type(annotation));
}

// AI generated by: Claude Code (claude-sonnet-5-5)
