// type is the IR type to store and slot the ir_index (the caller numbers it).
static void declare_variable(Ctx* ctx,
                             Sema* sema,
                             AstNode* ident,
                             IrType type,
                             bool is_val,
                             size_t slot) {
  const char* name = ast_node_get_name(ident);
  if (symtable_lookup(sema->scope, (char*)name, false) != NULL)
    THROW(E_SEMANTIC_REDEFINITION_ERROR, "redefinition of '%s' at %d:%d", name,
          ast_node_get_line(ident), ast_node_get_column(ident));

  SymtableData data = {
      .symbol_type = SYMBOL_VARIABLE,
      .ir_type = type,
      .ir_index = slot,
      .param_count = 0,
      .param_types = NULL,
      .is_val = is_val,
  };
  symtable_insert(ctx, sema->scope, (char*)name, data);
  ast_node_set_symbol(ident, symtable_lookup(sema->scope, (char*)name, false));
}

// AI generated by: Claude Code (claude-sonnet-5-5)
// Prompt: "implementation done using skill: mattpocock-skills:implement-spec,
// ticket 03: scopes, declarations, resolution and shadowing"
// Changes:
// New: resolves an identifier use to a variable symbol, searching from the
// current scope outward. Functions live only in the global scope, the last one
// searched, so a hit that is not a variable means no variable of that name is
// visible (exit 3). Points the identifier at the symbol and returns it.
static SymtableData* resolve_variable(Ctx* ctx, Sema* sema, AstNode* ident) {
  const char* name = ast_node_get_name(ident);
  SymtableData* symbol = symtable_lookup(sema->scope, (char*)name, true);
  if (symbol == NULL || symbol->symbol_type != SYMBOL_VARIABLE)
    THROW(E_SEMANTIC_UNDEFINED_ERROR, "undefined variable '%s' at %d:%d", name,
          ast_node_get_line(ident), ast_node_get_column(ident));
  ast_node_set_symbol(ident, symbol);
  return symbol;
}

