// small ir_index of the IR function type.
static bool is_builtin_symbol(Ctx* ctx,
                              const Sema* sema,
                              const SymtableData* symbol) {
  if (symbol->ir_index >= ast_node_get_child_count(sema->program))
    return true;
  AstNode* def = NULL;
  AstNode* ident = NULL;
  ast_node_get_child(ctx, sema->program, symbol->ir_index, &def);
  ast_node_get_child(ctx, def, DEF_IDENT, &ident);
  return ast_node_get_symbol(ident) != symbol;
}

