// Changes:
// New: a BLOCK. Opens the block's scope (nested in the current one, owned by
// the BLOCK), checks its statements in it and makes the enclosing scope current
// again. The scope is not destroyed, the BLOCK keeps it.
static void check_block(Ctx* ctx, Sema* sema, AstNode* block) {
  Symtable* outer = sema->scope;
  sema->scope = ast_node_attach_scope(ctx, block, outer);
  size_t count = ast_node_get_child_count(block);
  for (size_t i = 0; i < count; i++) {
    AstNode* stmt = NULL;
    ast_node_get_child(ctx, block, i, &stmt);
    check_stmt(ctx, sema, stmt);
  }
  sema->scope = outer;
}

